    # Find the uniform separator that divides the grid into equal panels.
    sep = None
    for j in range(w):
        if h and all(row[j] == grid[0][j] for row in grid):
            if j == w // 2 and w % 2 == 1:
                sep = ("col", j)
                break
    if sep is None:
        for i in range(h):
            if len(set(grid[i])) == 1 and i == h // 2 and h % 2 == 1:
                sep = ("row", i)
                break

    if sep is None:
        return [row[:] for row in grid]

    if sep[0] == "col":
        j = sep[1]
        a = [row[:j] for row in grid]
        b = [row[j + 1:] for row in grid]
    else:
        i = sep[1]
        a, b = grid[:i], grid[i + 1:]

    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    color = next(iter(shared))
    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
